    let j=stageIndex[stage], L=stage>=1?config.effects[1]*Math.log1p(level):0;
    if(lastDist&&lastDist.j===j&&lastDist.L===L)return lastDist;
    let h=histograms[j], weights=h.delta.map(d=>Math.pow(2,L*d)), sum=0;
    for(let i=0;i<weights.length;i++)sum+=weights[i]*h.c[i]*h.g[i];
