function drawVisualRoll(s,stage,level){
    const d=sigmaDist(stage,level),groups=getGroups();
    if(!livePools[d.j]){
        const pools=d.h.c.map(()=>({ids:[],cum:[],n:0}));
        for(let g=0;g<groups.n.length;g++){
            const b=pools[groups.bucket[d.j][g]];b.ids.push(g);b.n+=groups.n[g];b.cum.push(b.n);
        }
        // Only the active distribution is needed on a mobile device.
        livePools={};livePools[d.j]=pools;
    }
    const stream={rng:s.visualSeed},buckets=livePools[d.j],weights=[];
    let mass=0;
    for(let i=0;i<buckets.length;i++){mass+=buckets[i].n*d.p[i];weights.push(mass);}
    const b=buckets[pickIndex(weights,randomOpen(stream)*mass)];
    const g=b.ids[pickIndex(b.cum,randomOpen(stream)*b.n)];
    const roll=sampleNumber(g,Math.floor(randomOpen(stream)*groups.n[g]));
    s.visualSeed=stream.rng;
    const result={g:g,roll:roll,t:s.time,stage:stage};
    s.rolls.unshift(result);if(s.rolls.length>20)s.rolls.pop();
    return result;
}
function six(n){return ("000000"+n).slice(-6);}
function beginReveal(ids){
    if(!state.notify||!ids.length)return;
    const best=ids.map(id=>roleById[id]).sort((a,b)=>roles[a].count-roles[b].count)[0];
    const event=roleEvent(roles[best].id),tier=visualTiers.indexOf(roles[best].rarity);
    activeReveal={event:event,i:best,tier:tier,age:0};
}
function visualTick(elapsed,newIds,offline){
    if(offline){activeReveal=null;returningFromOffline=true;return;}
    if(returningFromOffline){newIds=state.pending.concat(newIds);returningFromOffline=false;}
    if(activeReveal){activeReveal.age+=elapsed;if(activeReveal.age>=revealStyles[activeReveal.tier].duration)activeReveal=null;}
    if(newIds.length)beginReveal(newIds);
    liveAge+=elapsed;
    if(state.liveRolls&&liveAge>=2){
        drawVisualRoll(state,milestone.level,regular[1].level);liveAge=0;
    }
    if(!liveLabel)return;
    if(activeReveal&&state.notify){
        const a=activeReveal,style=revealStyles[a.tier],v=six(a.event.roll);
        const locked=!state.motion||a.tier<2?6:Math.min(6,1+Math.floor(a.age*(a.tier===5?4:6)));
        const digits=v.slice(0,locked)+"······".slice(locked);
        liveLabel.text=style.mark+" "+digits+" "+style.mark;
        liveLabel.textColor=Color.fromHex(style.color);
        liveLabel.fontSize=a.tier>=3&&state.motion&&a.age<1.4?18+Math.floor(3*Math.sin(Math.PI*a.age/1.4)):17;
        liveSummary.text=roles[a.i].rarity+" · "+roleName(a.i);
    }else{
        const last=state.rolls[0];liveLabel.textColor=Color.TEXT;liveLabel.fontSize=17;
        liveLabel.text=state.liveRolls&&last?six(last.roll):"";
        liveSummary.text=state.liveRolls?"Live roll":"";
    }
}
function recentRolls(){
    const rows=[label("Foreground samples use current Luck. These previews do not award discoveries.")];
    for(let r of state.rolls)rows.push(button(six(r.roll)+"   ·   "+stamp(r.t),()=>go("roll",r)));
    if(!state.rolls.length)rows.push(label(tr().none));
    return panel(rows);
}


var rho,regular=[],milestone,permanents=[],productionCache=null,lastUi=0;
var tr=()=>strings.en;
var roleName=i=>roles[i].en;
var roleCondition=i=>roles[i].condition;
var getName=()=>name;
var getDescription=()=>tr().description;
function formatLog(log){
    if(log===null||log===-Infinity)return "0";
    if(!state.scientific)return big(log).toString(3);
    let exponent=Math.floor(log);return Math.pow(10,log-exponent).toFixed(3)+"e"+exponent;
}
function formatBig(v){return v.sign===0?"0":formatLog(v.abs().log10().toNumber());}
function stamp(seconds){
    let days=Math.floor(seconds/86400),h=Math.floor(seconds/3600)%24,m=Math.floor(seconds/60)%60,s=Math.floor(seconds)%60;
    let two=n=>(n<10?"0":"")+n;
    return days+tr().day+" "+two(h)+":"+two(m)+":"+two(s);
}
function effects(i,k){
    let e=config.effects;
    if(i===0)return formatLog(k*Math.log10(e[0]))+"/s";
    if(i===1)return (e[1]*Math.log1p(k)).toFixed(4);
    if(i===2)return "+"+(e[2]*k).toFixed(3);
    if(i===3||i===5){let a=(i===3?.05:.03)+e[i]*k;return (100*a/(1+a)).toFixed(2)+"%";}
    return "×"+formatLog(logPlus(0,Math.log10(i===4?.5:.8)+k*Math.log10(e[i])));
}
function updateAvailability(){
    for(let i=0;i<7;i++){regular[i].isAvailable=milestone.level>=gates[i];regular[i].isAutoBuyable=!state.managed;}
    let t=tr(),k=milestone.level;
    milestone.description=k<9?"M"+(k+1)+" · "+t.milestones[k]:t.maxM;
    milestone.info=k<9?t.mHelp[k]:t.mHelp[8];
    for(let i=0;i<permanents.length;i++){
        permanents[i].description=t.permanentNames[i];permanents[i].info=t.permanentHelp[i];
    }
    refreshButton();
}
function init(){
    rho=theory.createCurrency();
    for(let i=0;i<7;i++){
        let u=theory.createUpgrade(i,rho,new ExponentialCost(big(config.logPrices[i]),Math.log2(config.ratios[i])));
        u.getDescription=()=>tr().variables[i]+"  "+symbols[i]+" = "+effects(i,u.level);
        u.getInfo=amount=>tr().variableHelp[i]+"\n"+effects(i,u.level)+" → "+effects(i,u.level+Math.max(1,amount));
        u.bought=amount=>{if(amount>0)state.buys[i]+=amount;};
        regular.push(u);
    }
    permanents=[theory.createPublicationUpgrade(0,rho,big(6)),theory.createBuyAllUpgrade(1,rho,BigNumber.ZERO),theory.createAutoBuyerUpgrade(2,rho,BigNumber.ZERO)];
    theory.setMilestoneCost(new CustomCost(i=>BigNumber.from(config.thresholds[Math.min(8,i)])));
    milestone=theory.createMilestoneUpgrade(0,9);milestone.canBeRefunded=()=>false;
    milestone.boughtOrRefunded=()=>{updateAvailability();invalidate();};
    updateAvailability();
}
function invalidate(){
    lastUi=state.time;theory.invalidatePrimaryEquation();theory.invalidateSecondaryEquation();theory.invalidateTertiaryEquation();
    refreshButton();
}
function current(){return economic(milestone.level,regular.map(u=>u.level));}
var tick=(elapsed,multiplier)=>{
    if(!(elapsed>0&&isFinite(elapsed)&&multiplier>0&&isFinite(multiplier)))return;
    let offline=game.isCalculatingOfflineProgress,old=state.foundCount,prior=state.history.length;
    let remaining=elapsed;while(remaining>0)remaining=replayElapsed(remaining,multiplier);
    if(offline)state.offline+=elapsed;
    let added=[];for(let i=prior;i<state.history.length;i++)added=added.concat(state.history[i].ids);
    visualTick(elapsed,added,offline);
    if(!offline&&(state.time-lastUi>=1||old!==state.foundCount))invalidate();
    requestPublication();
};
function requestPublication(){
    if(!state.autoPub||(game.isCalculatingOfflineProgress&&!state.allowOffline)||!theory.isPublicationAvailable||!theory.canPublish)return false;
    let prev=theory.tauPublished.max(BigNumber.ONE).log10().toNumber();
    let currentTau=theory.tau.max(BigNumber.ONE).log10().toNumber();
    if(currentTau<prev+config.stride)return false;
    let count=state.publications;theory.publish();return state.publications!==count;
}
var postPublish=()=>{state.publications++;productionCache=null;invalidate();};
var getTau=()=>state.peak===-300?rho.value:rho.value.max(big(state.peak));
var getCurrencyFromTau=tau=>[tau,rho.symbol];
var getPublicationMultiplier=tau=>big(publicationLog(tau.max(BigNumber.ONE).log10().toNumber()));
var getPublicationMultiplierFormula=()=> "10^{F(\\log_{10}\\tau)}";
var getPrimaryEquation=()=> "\\dot\\rho= B_{\\rm pub}\\, n\\,\\frac{G_j}{11}\\,F_{CD}";
var getSecondaryEquation=()=>{let e=current();return "L="+e.L.toFixed(3)+"\\quad Q="+e.Q.toFixed(3)+"\\quad M="+milestone.level;};
var getTertiaryEquation=()=> "\\dot\\rho="+formatLog(current().log+theory.publicationMultiplier.log10().toNumber())+"\\quad B_{\\rm pub}="+formatBig(theory.publicationMultiplier);



var overlayButton=null, dialog=null, navigation=[], warningSeen=false;
var browse={q:"",family:"",tier:"",status:0,sort:0,page:0}, pageSize=9;
var familyKeys=Object.keys(strings.en.familyNames);
function label(text){return ui.createLabel({text:text,fontSize:14});}
function heading(text){return ui.createLabel({text:text,fontSize:17,fontAttributes:FontAttributes.BOLD});}
function button(text,click){return ui.createButton({text:text,onClicked:click,cornerRadius:6});}
function stack(children){return ui.createStackLayout({children:children,spacing:5});}
function pair(a,b){a.column=0;b.column=1;return ui.createGrid({columnDefinitions:["*","*"],children:[a,b]});}
function panel(children){return ui.createScrollView({content:stack(children)});}
function go(key,arg){navigation.push({key:key,arg:arg});paint();}
function back(){if(navigation.length>1){navigation.pop();paint();}else if(dialog)dialog.hide();}
function refreshButton(){
    if(overlayButton){let id=state.pending[state.pending.length-1],i=roleById[id];overlayButton.text=state.notify&&id?tr().new+" · "+state.pending.length+"\n"+roleName(i)+" · "+tr().tiers[roles[i].rarity]+"\n"+stamp(state.found[id]):tr().journal;}
}
var getEquationOverlay=()=>{
    overlayButton=button(tr().journal,openJournal);overlayButton.fontSize=12;
    overlayButton.horizontalOptions=LayoutOptions.END;overlayButton.verticalOptions=LayoutOptions.END;
    refreshButton();
    liveLabel=heading("");liveSummary=label("");liveSummary.fontSize=11;
    let display=stack([liveLabel,liveSummary]);display.horizontalOptions=LayoutOptions.START;
    display.verticalOptions=LayoutOptions.START;display.inputTransparent=true;
    return ui.createGrid({inputTransparent:true,cascadeInputTransparent:false,children:[display,overlayButton]});
};
function openJournal(){
    if(game.isCalculatingOfflineProgress||dialog)return;
    navigation=[{key:"home"}];
    dialog=ui.createPopup({title:tr().journal,isPeekable:true,closeOnBackButtonClicked:true,closeOnBackgroundClicked:true,
        onDisappearing:()=>{dialog=null;navigation=[];}});
    paint();dialog.show();
}
function opts(key,value){return tr()[key]+" · "+value;}
function roleButton(i){return button((state.found[roles[i].id]!==undefined?"● ":"○ ")+roleName(i),()=>go("detail",i));}
function showInbox(){
    let ids=state.pending.slice();go("inbox",ids);state.pending=[];refreshButton();
}
function home(){
    let t=tr(),n=state.foundCount,children=[heading(t.collection+"   "+n+" / 177"),
        ui.createProgressBar({progress:n/177}),label((n/177*100).toFixed(1)+"%   ·   "+t.missing+" "+(177-n))];
    if(restoreWarning)children.push(label(t.savedError));
    if(state.pending.length)children.push(button(t.seen+"  ·  "+state.pending.length,showInbox));
    children.push(button("Recent rolls",()=>go("rolls")),button(t.list,()=>go("browse")),
        pair(button(t.history,()=>go("history",0)),button(t.stats,()=>go("stats"))),
        pair(button(t.help,()=>go("help")),button(t.settings,()=>go("settings"))));
    if(!state.compact){
        let recent=Object.keys(state.found).map(id=>roleById[id]).sort((a,b)=>state.found[roles[b].id]-state.found[roles[a].id]);
        children.push(heading(t.recent));if(!recent.length)children.push(label(t.none));
        for(let i of recent.slice(0,3))children.push(roleButton(i));
        if(recent.length){children.push(heading(t.rarest));for(let i of recent.sort((a,b)=>roles[a].count-roles[b].count).slice(0,3))children.push(roleButton(i));}
    }
    children.push(heading(t.families));
    for(let f of familyKeys){
        let subset=roles.filter(r=>r.family===f),nFound=subset.filter(r=>state.found[r.id]!==undefined).length;
        children.push(button(t.familyNames[f]+"   "+nFound+" / "+subset.length,()=>{
            browse={q:"",family:f,tier:"",status:0,sort:0,page:0};go("browse");
        }));
    }
    return panel(children);
}
function filteredRoles(){
    let q=browse.q.trim().toLowerCase(),ids=[];
    for(let i=0;i<roles.length;i++){
        let r=roles[i],seen=state.found[r.id]!==undefined;
        if(browse.tier&&r.rarity!==browse.tier)continue;
        if(browse.family&&browse.family!==r.family||browse.status===1&&!seen||browse.status===2&&seen)continue;
        if(q&&[r.en,r.description,r.condition].concat(r.aliases).join(" ").toLowerCase().indexOf(q)<0)continue;
        ids.push(i);
    }
    let cmp=(a,b)=>roleName(a)<roleName(b)?-1:roleName(a)>roleName(b)?1:0;
    if(browse.sort===3){
        const dist=sigmaDist(milestone.level,regular[1].level),odds={};
        ids.forEach(i=>odds[i]=logOdds(i,dist));
        return ids.sort((a,b)=>odds[b]-odds[a]||cmp(a,b));
    }
    return ids.sort((a,b)=>(browse.sort===1?roles[a].count-roles[b].count:browse.sort===2?(state.found[roles[b].id]===undefined?-1:state.found[roles[b].id])-(state.found[roles[a].id]===undefined?-1:state.found[roles[a].id]):0)||cmp(a,b));
}
function roleList(){
    let t=tr(),results=ui.createStackLayout({spacing:4}),status=[t.all,t.found,t.missing];
    function render(){
        const list=filteredRoles(),pages=Math.max(1,Math.ceil(list.length/pageSize));
        browse.page=Math.min(browse.page,pages-1);
        let rows=[label(list.length+" / 177   ·   "+t.page+" "+(browse.page+1)+" / "+pages)];
        for(let i of list.slice(browse.page*pageSize,(browse.page+1)*pageSize)){
            let r=roles[i],badge=t.tiers[r.rarity]+" · "+(r.production?t.production:t.display);
            rows.push(button((state.found[r.id]!==undefined?"● ":"○ ")+roleName(i)+(state.compact?"":"\n"+badge),()=>go("detail",i)));
        }
        if(!list.length)rows.push(label(t.noResults));
        if(pages>1)rows.push(pair(button("‹ "+t.previous,()=>{browse.page=Math.max(0,browse.page-1);render();}),
            button(t.next+" ›",()=>{browse.page=Math.min(pages-1,browse.page+1);render();})));
        results.children=rows;
    }
    const query=ui.createEntry({text:browse.q,placeholder:t.search,onTextChanged:(_,value)=>{browse.q=value||"";browse.page=0;render();}});
    let controls=[query,pair(button(opts("family",browse.family?t.familyNames[browse.family]:t.all),()=>go("family")),button("Rarity · "+(browse.tier||t.all),()=>go("tier"))),
        pair(button(opts("status",status[browse.status]),()=>{browse.status=(browse.status+1)%3;browse.page=0;paint();}),
        button(opts("sort",t.sorts[browse.sort]),()=>{browse.sort=(browse.sort+1)%t.sorts.length;browse.page=0;paint();})),results];
    render();return panel(controls);
}
function familySelect(){
    let all=[""].concat(familyKeys);
    return panel(all.map(f=>button(f?tr().familyNames[f]:tr().all,()=>{browse.family=f;browse.page=0;back();})));
}
function roleEvent(id){return state.history.find(e=>e.ids.indexOf(id)>=0);}
function related(i){return roles.map((_,j)=>j).filter(j=>j!==i&&links[i][j]>0).sort((a,b)=>links[i][b]-links[i][a]||roles[a].count-roles[b].count);}
function detail(i){
    let r=roles[i],t=tr(),date=state.found[r.id],event=roleEvent(r.id),z=logOdds(i,sigmaDist(milestone.level,regular[1].level))/Math.LN10;
    let probability=z< -7?"10^("+z.toFixed(4)+")":(Math.min(1,Math.pow(10,z))*100).toPrecision(5)+"%";
    let rows=[heading(roleName(i)),label(t.tiers[r.rarity]+"   ·   "+t.familyNames[r.family]+"   ·   "+(r.production?t.production:t.display)),
        heading(t.condition),label(roleCondition(i)),label(opts("example",r.example)),
        heading("Information content"),label((-Math.log2(r.count/1000000)).toFixed(4)+" bits · −log₂(base odds)"),
        heading(t.base),label(r.count+" / 1,000,000"),heading(t.current),label(probability+"   (L="+current().L.toFixed(3)+")"),
        label(opts("status",date===undefined?t.missing:t.found+" · "+stamp(date))),
        label(t.observeAt+r.discovery_unlock+(r.production?"   ·   "+t.scoreAt+r.production_unlock:""))];
    if(r.aliases.length)rows.push(heading(t.aliases),label(r.aliases.join(" · ")));
    if(event)rows.push(button(t.matches,()=>go("event",event)));
    rows.push(heading(t.related));
    let rel=related(i);if(!rel.length)rows.push(label(t.noOverlap));
    for(let j of rel.slice(0,4))rows.push(button(roleName(j)+" · "+links[i][j]+" "+t.both,()=>go("detail",j)));
    if(rel.length>4)rows.push(button(t.more+" ("+rel.length+")",()=>go("related",i)));
    return panel(rows);
}
function timeline(page){
    let t=tr(),events=state.history.slice().reverse(),pages=Math.max(1,Math.ceil(events.length/pageSize));
    let rows=events.slice(page*pageSize,(page+1)*pageSize).map(e=>button(stamp(e.t)+"  ·  "+e.ids.map(id=>roleName(roleById[id])).join(" / "),()=>go("event",e)));
    if(!rows.length)rows.push(label(t.none));
    if(pages>1)rows.push(pair(button(t.previous,()=>{navigation[navigation.length-1].arg=Math.max(0,page-1);paint();}),
        button(t.next,()=>{navigation[navigation.length-1].arg=Math.min(pages-1,page+1);paint();})));
    return panel(rows);
}
function eventPage(e){
    let t=tr(),rows=[heading(("000000"+e.roll).slice(-6)),label(stamp(e.t)+"   ·   M"+e.stage),heading(t.newAt)];
    for(let id of e.ids){
        const i=roleById[id];rows.push(button(roleName(i)+" · "+t.tiers[roles[i].rarity],()=>go("detail",i)));
        if(!state.compact)rows.push(label(roles[i].discovery_en));
    }
    rows.push(heading(t.matches));for(let i of matchingGroup(e))rows.push(roleButton(i));
    return panel(rows);
}
function statsPage(){
    let t=tr(),k=regular.map(u=>u.level),e=current(),d=sigmaDist(milestone.level,k[1]);
    let rows=[heading("ρ   "+formatBig(rho.value)),label(opts("rate",formatLog(e.log+theory.publicationMultiplier.log10().toNumber()))),
        label(opts("mult","×"+formatBig(theory.publicationMultiplier))),label(opts("pubNext","×"+formatBig(theory.nextPublicationMultiplier))),
        label(opts("pubs",state.publications)),label(opts("lifetime",formatLog(state.lifetimeLog))),
        label(opts("nextM",milestone.level===9?t.maxM:"10^"+config.thresholds[milestone.level]+" τ")),
        label(opts("goal","10^"+(theory.tauPublished.max(BigNumber.ONE).log10().toNumber()+6).toFixed(2)+" τ")),
        heading(t.sig+"   "+d.h.K),label("L = "+e.L.toFixed(4)+"   Q = "+e.Q.toFixed(4)),
        label(opts("score",formatLog(e.G*Math.log10(2)))),label(opts("cFactor",(1+e.C).toPrecision(4))),
        label(opts("dFactor",(1+e.D).toPrecision(4))),label(opts("joint",e.event.toPrecision(4))),
        heading(t.collection+"   "+state.foundCount+"/177"),label(opts("obs",state.expectedObservations.toPrecision(6))),
        label(opts("obsRate",observationRate(milestone.level,d).toPrecision(5))),label(opts("time",stamp(state.time))),
        label(opts("offline",stamp(state.offline))),heading(t.buys)];
    for(let i=0;i<7;i++)rows.push(label(t.variables[i]+"   "+state.buys[i]+"   ·   Lv."+k[i]));
    return panel(rows);
}
function settingsPage(){
    let t=tr(),rows=[];
    for(let item of [["motion","motion",[t.no,t.yes]],["liveRolls","liveRolls",[t.no,t.yes]],["scientific","format",t.formats],["compact","layout",t.layouts],["managed","buyer",t.buyModes],["notify","notices",[t.no,t.yes]],
        ["autoPub","autoPub",[t.no,t.yes]],["allowOffline","offlinePub",[t.no,t.yes]]]){
        rows.push(button(opts(item[1],item[2][state[item[0]]?1:0]),()=>{
            state[item[0]]=!state[item[0]];if(item[0]==="notify"&&!state.notify)state.pending=[];
            if(item[0]==="managed")updateAvailability();invalidate();paint();
        }));
    }
    return panel(rows);
}
function paint(){
    if(!dialog)return;
    let v=navigation[navigation.length-1],t=tr(),body,title;
    switch(v.key){
    case "home":body=home();title=t.journal;break;
    case "browse":body=roleList();title=t.atlas;break;
    case "tier":body=panel([""].concat(visualTiers).map(tier=>button(tier||t.all,()=>{browse.tier=tier;browse.page=0;back();})));title="Rarity";break;
    case "rolls":body=recentRolls();title="Recent rolls";break;
    case "roll":body=panel([heading(six(v.arg.roll)),label(stamp(v.arg.t)+"   ·   M"+v.arg.stage),heading(t.matches)].concat(matchingGroup(v.arg).map(roleButton)));title="Live roll";break;
    case "family":body=familySelect();title=t.family;break;
    case "detail":body=detail(v.arg);title=roleName(v.arg);break;
    case "related":body=panel(related(v.arg).map(j=>button(roleName(j)+" · "+links[v.arg][j]+" "+t.both,()=>go("detail",j))));title=t.related;break;
    case "stats":body=statsPage();title=t.stats;break;
    case "settings":body=settingsPage();title=t.settings;break;
    case "history":body=timeline(v.arg);title=t.history;break;
    case "event":body=eventPage(v.arg);title=t.captured;break;
    case "inbox":body=panel(v.arg.map(id=>{let i=roleById[id];return button(roleName(i)+" · "+t.tiers[roles[i].rarity]+" · "+stamp(state.found[id]),()=>go("detail",i));}));title=t.new;break;
    case "help":body=panel(t.guide.map(s=>label(s)));title=t.help;break;
    }
    let bar=navigation.length>1?pair(button("‹ "+t.back,back),button(t.close,()=>dialog.hide())):button(t.close,()=>dialog.hide());
    bar.row=1;dialog.title=title;dialog.content=ui.createGrid({rowDefinitions:["*","auto"],heightRequest:Math.max(150,Math.min(560,ui.screenHeight*.66)),children:[body,bar]});
}



